const items = $input.all();

// Función helper para redondear minutos en :45 a la hora siguiente (ej: "07:45" -> "08:00")
function redondearHora(horaStr) {
  if (!horaStr || !horaStr.includes(':')) return horaStr;

  let [horas, minutos] = horaStr.split(':').map(Number);

  if (minutos === 45) {
    horas = (horas + 1) % 24;
    minutos = 0;
  }

  const hh = String(horas).padStart(2, '0');
  const mm = String(minutos).padStart(2, '0');
  return `${hh}:${mm}`;
}

// Datos recibidos del trigger
const trigger = $('When Executed by Another Workflow').first().json;
const fechaBuscada = trigger.fecha;   // ej: "2026-07-22"
const horaOriginal = trigger.hora;    // ej: "07:45"
const horaBuscada = redondearHora(horaOriginal); // ej: "08:00"
const modeloBuscado = trigger.Modelo || trigger.modelo; // ej: "Corolla"

if (!fechaBuscada || !horaBuscada) {
  throw new Error('Buscar_Turno_Seleccionado: faltan los parámetros "fecha" y/o "hora" recibidos del workflow.');
}

// Obtención de la duración matcheando el modelo con la columna de Google Sheets
const dataSheet = $('Get row(s) in sheet').first().json;
let duracion = null;

if (modeloBuscado && dataSheet) {
  // 1. Intento de búsqueda directa (exacta)
  duracion = dataSheet[modeloBuscado];

  // 2. Respaldo insensible a mayúsculas/minúsculas
  if (!duracion) {
    const claveEncontrada = Object.keys(dataSheet).find(
      key => key.toLowerCase().trim() === modeloBuscado.toLowerCase().trim()
    );
    if (claveEncontrada) {
      duracion = dataSheet[claveEncontrada];
    }
  }
}

let turnoEncontrado = null;

if (items && items.length > 0) {
  for (const item of items) {
    if (!item || !item.json) continue;
    const data = item.json;

    let dia, inicio, fin;

    if (data.start && data.start.dateTime && data.end && data.end.dateTime) {
      // Estructura tipo evento de Google Calendar
      dia = data.start.dateTime.split('T')[0];
      inicio = data.start.dateTime.split('T')[1].substring(0, 5);
      fin = data.end.dateTime.split('T')[1].substring(0, 5);
    } else {
      // Estructura tipo slot ya plano (dia/inicio/fin)
      dia = data.dia;
      inicio = data.inicio;
      fin = data.fin;
    }

    // Se compara por horaLlegada si está disponible; si no, por inicio como respaldo
    const horaLlegadaItem = data.horaLlegada || inicio;

    if (dia === fechaBuscada && redondearHora(horaLlegadaItem) === horaBuscada) {
      turnoEncontrado = {
        dia: dia,
        inicio: inicio,
        fin: fin,
        horaLlegada: data.horaLlegada || null,
        finalizacionLavado: data.finalizacionLavado || null
      };
      break;
    }
  }
}

if (turnoEncontrado) {
  // Se encontró un turno ocupado que coincide con fecha+hora → el slot NO está disponible
  return [{
    json: {
      disponible: false,
      mensaje: "El turno seleccionado ya se encuentra ocupado.",
      duracion: duracion,
      ...turnoEncontrado
    }
  }];
} else {
  // No se encontró ningún turno ocupado con esa fecha+hora → el slot SÍ está disponible
  return [{
    json: {
      disponible: true,
      mensaje: "El turno está disponible.",
      duracion: duracion,
      dia: fechaBuscada,
      inicio: null,
      fin: null,
      horaLlegada: horaBuscada,
      finalizacionLavado: null
    }
  }];
}

function calcularSieteDiasLaborables() {
  const hoy = new Date();

  // Lista de feriados
  const feriados = [
    // 2025
    '2025-01-01', // Año Nuevo
    '2025-03-03', // Carnaval
    '2025-03-04', // Carnaval
    '2025-03-24', // Día Nacional de la Memoria por la Verdad y la Justicia
    '2025-04-18', // Viernes Santo
    '2025-04-02', // Día del Veterano y de los Caídos en la Guerra de Malvinas
    '2025-05-01', // Día del Trabajador
    '2025-05-25', // Día de la Revolución de Mayo
    '2025-06-20', // Paso a la Inmortalidad del General Manuel Belgrano
    '2025-06-21', // Paso a la Inmortalidad del General Manuel Belgrano (trasladado)
    '2025-06-22', // Paso a la Inmortalidad del General Manuel Belgrano (puente)
    '2025-07-09', // Día de la Independencia
    '2025-08-17', // Paso a la Inmortalidad del General José de San Martín
    '2025-10-12', // Día del Respeto a la Diversidad Cultural
    '2025-11-24', // Día de la Soberanía Nacional
    '2025-12-08', // Inmaculada Concepción de María
    '2025-12-25', // Navidad
  ];

  let diasLaborablesEncontrados = 0;
  let i = 1; // Empezar desde mañana
  let fechaFinal = null;

  // Buscar hasta encontrar exactamente 7 días laborables
  while (diasLaborablesEncontrados < 7) {
    const fecha = new Date(hoy);
    fecha.setDate(hoy.getDate() + i);

    const fechaFormateada = fecha.toISOString().split('T')[0];
    const dayOfWeek = fecha.getDay(); // 0=domingo, 1=lunes, ..., 6=sábado

    // Verificar si es día laborable (lunes a viernes) y no es feriado
    const esLaborable = dayOfWeek >= 1 && dayOfWeek <= 5; // lunes a viernes
    const noEsFeriado = !feriados.includes(fechaFormateada);

    if (esLaborable && noEsFeriado) {
      diasLaborablesEncontrados++;
      if (diasLaborablesEncontrados === 7) {
        // Establecer hora específica y formato completo
        fecha.setHours(12, 44, 14, 1); // 12:44:14.001
        fechaFinal = fecha.toISOString().replace('Z', '-04:00'); // Cambiar Z por -04:00
      }
    }

    i++;
  }

  return fechaFinal;
}

const sieteDias = calcularSieteDiasLaborables();

return [{
  json: {
    sieteDias: sieteDias
  }
}];

